-- ═════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
-- 20261231400000 — QuickBooks: a shared QuickBooks company no longer blocks a disconnect (launch blocker B1, sandbox acceptance 2026-11-23).
-- AUTHORED, NOT APPLIED. Changes no row by itself; replaces one function body.
--   WHY: qbo_begin_disconnect refused 'shared_connection' whenever another ACTIVE connection held the same QuickBooks company (equal keyed
--   index). With two or more such connections none could ever be disconnected, and no administrator path existed; the refusal also told one
--   workspace that another uses the same company. Intuit requires that a connection can always be disconnected.
--   WHAT IT DOES: qbo_begin_disconnect (same signature, SECURITY DEFINER, service role only) is replaced by the part 2 body with three edits:
--     · while another active connection shares the realm, the disconnect is LOCAL: the connection becomes 'disconnected', its refresh token is
--       destroyed, and the operation is recorded as 'local_only' with no pending envelope; nothing is sent to Intuit (a revocation there would
--       end the authorisation the other connection still uses);
--     · the last active connection's disconnect revokes at Intuit exactly as before ('pending' -> 'revoked');
--     · the answer for a shared realm is 'local_only', indistinguishable from a connection that holds no token.
--   UNCHANGED: the index-rotation refusal ('rotation_in_progress', checked first, so a sharer is never missed mid-rotation), request idempotency,
--   the per-realm lock, the realm protection copied to the operation (envelope + index, no plaintext), every table, guard and constraint.
--   No Edge Function change is required: qbo-disconnect already answers 'local_only' (HTTP 202) for that outcome.
-- SELF-VERIFYING: the installed body must be the reviewed part 2 body (3782a5b86690…) or already this one (a replay is a no-op);
-- the result is pinned by SHA-256 together with its security attributes and grants; any difference fails the block and nothing changes.
-- Generated by scripts/release/genQboSharedRealmDisconnect.mjs from 20261231200000_qbo_realm_protection_cutover_functions.sql; regenerate, never hand-edit.
-- ═════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
DO $qbo_shared_realm_local_disconnect$
DECLARE
  v_old constant text := '3782a5b866900544e5d680125d5a775573bb1861a57d4d8c439555a4f0f68f9e';
  v_new constant text := '864d8cb71cc6df9c51baba97acddacf13018482f4f8a8ea446e247afaddb2a02';
  v_now text;
BEGIN
  v_now := (SELECT encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex') FROM pg_proc p WHERE p.oid = to_regprocedure('public.qbo_begin_disconnect(uuid,uuid,uuid)'));
  IF v_now = v_new THEN RETURN; END IF;   -- replay
  -- PREFLIGHT: Phase C v2 complete (the redaction's final rule present) and the reviewed part 2 body installed.
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chk_qbo_connections_live_no_plaintext')
     OR to_regprocedure('public.qbo_index_key_mixed(text)') IS NULL OR v_now IS DISTINCT FROM v_old THEN
    RAISE EXCEPTION 'PREFLIGHT_REFUSED: realm protection Phase C v2 (all four parts) with the reviewed qbo_begin_disconnect body must be installed; nothing was changed' USING ERRCODE = 'P0001';
  END IF;

  CREATE OR REPLACE FUNCTION public.qbo_begin_disconnect(p_connection uuid,p_actor uuid,p_request uuid)
  RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $f$
  DECLARE c public.qbo_connections; o public.qbo_disconnect_operations; ticket uuid; v_shared boolean; v_revoke boolean;
  BEGIN
   PERFORM pg_advisory_xact_lock_shared(hashtextextended('qbo-index-rotation', 0));   -- [Phase C v2] no index rotation can commit inside this call
   SELECT * INTO c FROM public.qbo_connections WHERE id=p_connection;
   -- [20261231100000] the per-realm lock and the shared-realm check use the index (a terminal pre-protection row locks on its own id).
   IF FOUND THEN PERFORM pg_advisory_xact_lock(hashtextextended('qbo-connect:'||c.environment||':'||coalesce(c.realm_index,c.id::text),0)); END IF;
   SELECT * INTO c FROM public.qbo_connections WHERE id=p_connection FOR UPDATE;
   IF NOT FOUND OR NOT public.qbo_connector_basis(p_actor,c.company_id) THEN RETURN jsonb_build_object('outcome','forbidden'); END IF;
   IF p_request IS NULL THEN RETURN jsonb_build_object('outcome','invalid_request'); END IF;
   SELECT * INTO o FROM public.qbo_disconnect_operations WHERE connection_id=c.id;
   IF FOUND THEN
    IF o.request_id<>p_request OR o.actor_user_id<>p_actor THEN RETURN jsonb_build_object('outcome','request_conflict'); END IF;
    IF o.outcome='pending' THEN
     IF o.revoke_lease_until>clock_timestamp() THEN RETURN jsonb_build_object('outcome','revocation_busy'); END IF;
     ticket:=gen_random_uuid(); UPDATE public.qbo_disconnect_operations SET revoke_lease_id=ticket,revoke_lease_until=clock_timestamp()+interval '45 seconds' WHERE connection_id=c.id;
    END IF;
    RETURN jsonb_build_object('outcome',o.outcome,'leaseId',ticket,'envelope',o.pending_envelope,'companyId',c.company_id,'environment',c.environment,'realmEnvelope',o.realm_envelope,'realmIndex',o.realm_index);
   END IF;
   IF EXISTS(SELECT 1 FROM public.qbo_disconnect_operations WHERE request_id=p_request) THEN RETURN jsonb_build_object('outcome','request_conflict'); END IF;
   IF c.status='disconnected' THEN RETURN jsonb_build_object('outcome','local_only'); END IF;
   IF c.refresh_lease_until>clock_timestamp() THEN RETURN jsonb_build_object('outcome','busy'); END IF;
   -- [Phase C v2] the shared-realm check compares indexes: refused while they could be made by different keys (it would miss a sharer and revoke
   -- a token another workspace still uses).
   IF c.realm_index IS NOT NULL AND public.qbo_index_key_mixed(split_part(c.realm_index, '.', 2)) THEN RETURN jsonb_build_object('outcome','rotation_in_progress'); END IF;
   -- [20261231400000] a realm another ACTIVE connection shares never blocks this workspace's disconnect (it used to answer 'shared_connection'
   -- for every sharer, so none could ever disconnect). The local disconnect always happens and this connection's token is destroyed; the
   -- revocation at Intuit, which ends the authorisation for EVERY connection to that QuickBooks company, is requested only by the last active
   -- connection. The answer is 'local_only', the same as for a connection that holds no token, so it never tells one workspace that another uses
   -- the same company. The per-realm lock taken above serialises sharers: exactly one of two simultaneous last disconnects sees no sharer.
   v_shared := EXISTS(SELECT 1 FROM public.qbo_connections x WHERE x.id<>c.id AND x.realm_index=c.realm_index AND x.environment=c.environment AND x.status='active');
   v_revoke := c.refresh_token_envelope IS NOT NULL AND NOT v_shared;
   INSERT INTO public.qbo_disconnect_operations(connection_id,request_id,actor_user_id,company_id,realm_id,environment,pending_envelope,outcome,realm_envelope,realm_index,realm_verified_at)
   VALUES(c.id,p_request,p_actor,c.company_id,NULL,c.environment,CASE WHEN v_revoke THEN c.refresh_token_envelope END,CASE WHEN v_revoke THEN 'pending' ELSE 'local_only' END,
          c.realm_envelope,c.realm_index,c.realm_verified_at);
   UPDATE public.qbo_connections SET status='disconnected',refresh_token_envelope=NULL,envelope_key_id=NULL,refresh_expires_at=NULL,hard_expires_at=NULL,
   refresh_lease_until=NULL,refresh_lease_id=NULL,disconnected_at=clock_timestamp() WHERE id=c.id;
   ticket:=gen_random_uuid(); UPDATE public.qbo_disconnect_operations SET revoke_lease_id=ticket,revoke_lease_until=clock_timestamp()+interval '45 seconds' WHERE connection_id=c.id AND outcome='pending';
   RETURN jsonb_build_object('outcome',CASE WHEN v_revoke THEN 'pending' ELSE 'local_only' END,'leaseId',CASE WHEN v_revoke THEN ticket END,'envelope',CASE WHEN v_revoke THEN c.refresh_token_envelope END,'companyId',c.company_id,
     'environment',c.environment,'realmEnvelope',c.realm_envelope,'realmIndex',c.realm_index);
  END $f$;

  -- POSTCONDITION: the body exactly as reviewed; SECURITY DEFINER with the fixed search_path; executable by the service role only.
  IF (SELECT encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex') FROM pg_proc p WHERE p.oid = to_regprocedure('public.qbo_begin_disconnect(uuid,uuid,uuid)')) IS DISTINCT FROM v_new
     OR NOT EXISTS (SELECT 1 FROM pg_proc p WHERE p.oid = to_regprocedure('public.qbo_begin_disconnect(uuid,uuid,uuid)') AND p.prosecdef AND p.proconfig = ARRAY['search_path=pg_catalog, public'])
     OR has_function_privilege('authenticated', 'public.qbo_begin_disconnect(uuid,uuid,uuid)', 'EXECUTE') OR has_function_privilege('anon', 'public.qbo_begin_disconnect(uuid,uuid,uuid)', 'EXECUTE')
     OR NOT has_function_privilege('service_role', 'public.qbo_begin_disconnect(uuid,uuid,uuid)', 'EXECUTE') THEN
    RAISE EXCEPTION 'POSTCONDITION: the shared-realm local disconnect is not installed exactly as reviewed' USING ERRCODE = 'P0001';
  END IF;
END
$qbo_shared_realm_local_disconnect$;
